/* استعلامات الوسائط لشاشات الهواتف المحمولة */
@media (max-width: 768px) {
  .container {
    display: flex;
    flex-direction: column;
    padding: 1rem;
  }
  .nav-menu {
    display: none; /* إخفاء القائمة في الشاشات الصغيرة */
  }
}

// الاستماع لنقر الزر وتعديل محتوى الصفحة ديناميكيًا
const button = document.querySelector('#counter-btn');
const display = document.querySelector('#count-display');
let count = 0;

button.addEventListener('click', () => {
  count++;
  display.textContent = 'عدد النقرات: ' + count;
  display.style.color = count % 2 === 0 ? '#138a55' : '#2f5bff';
});

